# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_labels


class RoundLabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [Span(7 * 60 + 58, 17 * 60 + 12)]
        self.assertEqual(
            round_labels(spans, 15), ["08:00-17:15 (9h 15m)"]
        )

    def test_halves_round_up(self):
        spans = [Span(9 * 60 + 7, 10 * 60 + 8)]
        self.assertEqual(
            round_labels(spans, 15), ["09:00-10:15 (1h 15m)"]
        )

    def test_exact_times_are_kept(self):
        spans = [Span(540, 1035)]
        self.assertEqual(
            round_labels(spans, 5), ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(0, 60), Span(120, 180)]
        self.assertEqual(len(round_labels(spans, 30)), 2)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)
